Funcion r <- Potencia(base Como Entero, exponente Como Entero)
  Definir r Como Entero;
  Si exponente = 0 Entonces
    r <- 1;
  Sino
    r <- base * Potencia(base, exponente - 1);
  FinSi
FinFuncion

Algoritmo Principal
  Definir base, exponente Como Entero;
  Leer base;
  Leer exponente;
  Escribir Potencia(base, exponente);
FinAlgoritmo
